const REF_REWARD=5000;
// One-time owner test grant; never converts to a future-token allocation.
const ownerId=(process.env.OWNER_TELEGRAM_ID||'').trim();
const ownerBonus=Number(process.env.OWNER_START_BONUS||0);
function applyOwnerGrant(uid,s,t){
 if(uid!==ownerId||!/^\d+$/.test(ownerId)||!Number.isSafeInteger(ownerBonus)||ownerBonus<1||ownerBonus>1e12||s.ownerTest||s.ownerProgressReset)return;
 G.tick(s,t);s.bonus+=ownerBonus;s.total+=ownerBonus;s.ownerTest=true;
}

// One-time additional developer pack; separate from the original owner grant.
const developerPackEnabled=process.env.OWNER_DEVELOPER_PACK==='1';
function applyDeveloperPack(uid,s,t){
 if(!developerPackEnabled||uid!==ownerId||!/^\d+$/.test(ownerId)||s.ownerDeveloperPackV1||s.ownerProgressReset)return false;
 G.tick(s,t);
 s.bonus+=300000000;
 s.total+=300000000;
 for(let i=0;i<G.boosts.length;i++)s.inventory[i]=(s.inventory[i]||0)+1;
 s.ownerTest=true;
 s.ownerDeveloperPackV1=true;
 return true;
}

// Only a verified, first-time Telegram account can trigger an invitation reward.
const referralGrace=48*3600000;
function account(uid,initData,t,providedCode=''){
 const fresh=!Object.hasOwn(users,uid);
 const s=fresh?(users[uid]=G.fresh(t)):users[uid];repairMiningState(s,t);
 if(fresh)s.refFirstSeen=t;
 const signed=new URLSearchParams(initData).get('start_param')||'';
 const code=signed||providedCode;
 const m=/^ref_([a-f0-9]{32})$/.exec(typeof code==='string'?code:'');
 const first=s.refFirstSeen||users._profiles?.[uid]?.firstSeen;
 if(s.referredBy||!m||(!fresh&&(!Number.isFinite(first)||t-first>referralGrace||t<first)))return s;
 const inviter=users._refCodes?.[m[1]]||Object.keys(users).find(id=>/^\d+$/.test(id)&&users[id]?.refCode===m[1]);
 if(inviter&&inviter!==uid&&Object.hasOwn(users,inviter)){
   const owner=users[inviter];G.tick(owner,t);owner.bonus+=REF_REWARD;owner.total+=REF_REWARD;
   owner.refCount=(owner.refCount||0)+1;owner.refEarned=(owner.refEarned||0)+REF_REWARD;
   s.referredBy=inviter;s.referredAt=t;
 }
 return s;
}
const miniAppName=/^[A-Za-z0-9_]{3,64}$/.test(process.env.BOT_APP_SHORT_NAME||'')?'/'+process.env.BOT_APP_SHORT_NAME:'';
