 return {count:s.refCount||0,earned:s.refEarned||0,url:botUsername?'https://t.me/'+botUsername+miniAppName+'?startapp=ref_'+s.refCode:'',code:'ref_'+s.refCode,joined:!!s.referredBy,canClaim:!s.referredBy&&Number.isFinite(first)&&Date.now()-first<=referralGrace};
