// V4: persistent game events, promotions and management; existing data schema preserved.
const V4_TERMS='2026-11-v4';
const cfg=()=>users._v4||(users._v4={promos:{},events:[],announcement:'',maintenance:false,audit:[],tickets:[]});
const activeEvent=t=>cfg().events.find(e=>e.start<=t&&e.end>t)||null;
const clean=(v,n=200)=>String(v??'').trim().slice(0,n);
