function logV4(uid,op,detail,t){const c=cfg();c.audit.unshift({uid,op,detail,t});c.audit=c.audit.slice(0,500);}
function transaction(fn){const before=JSON.stringify(users);try{const r=fn();save();return r}catch(e){const old=JSON.parse(before);for(const k of Object.keys(users))delete users[k];Object.assign(users,old);throw e;}}
function bonus(s,n){if(!Number.isFinite(s.bonus)||!Number.isFinite(s.total)||s.bonus+n>Number.MAX_SAFE_INTEGER||s.total+n>Number.MAX_SAFE_INTEGER)throw Error('Лимит баланса');s.bonus+=n;s.total+=n;}
function leaderboard(e){return Object.entries(e?.scores||{}).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,10).map(([id,score])=>({name:users._profiles?.[id]?.username?'@'+users._profiles[id].username:(users._profiles?.[id]?.name||'Игрок '+id.slice(-4)),score}));}
function publicV4(uid,t){const c=cfg(),e=activeEvent(t),s=users[uid];return {announcement:c.announcement,maintenance:c.maintenance&&!isAdmin(uid),blocked:!!s?.v4Blocked&&!isAdmin(uid),event:e?{kind:e.kind,name:eventNames[e.kind],end:e.end,mult:e.mult,reward:e.reward,left:e.kind==='chest'?Math.max(0,e.limit-Object.keys(e.claims).length):null,claimed:!!e.claims?.[uid],leaders:e.kind==='tournament'?leaderboard(e):[]}:null,latestTournament:(()=>{const x=c.events.find(v=>v.kind==='tournament'&&v.end<=t);return x?{leaders:leaderboard(x),end:x.end}:null})()};}
function adminV4(uid,b,t){if(!isAdmin(uid))throw Error('Нет доступа');const c=cfg(),e=activeEvent(t);if(b.op==='overview')return {event:e,announcement:c.announcement,maintenance:c.maintenance,promos:Object.entries(c.promos).map(([code,p])=>({code,amount:p.amount,limit:p.limit,used:Object.keys(p.used).length,end:p.end,disabled:!!p.disabled})),audit:c.audit.slice(0,25),tickets:c.tickets.slice(0,50),latestTournament:c.events.find(x=>x.kind==='tournament'&&x.end<=t)?leaderboard(c.events.find(x=>x.kind==='tournament'&&x.end<=t)):[]};
 return transaction(()=>{let detail='';switch(b.op){
 case 'start':{if(e)throw Error('Сначала останови текущее событие');const kind=b.kind;if(!Object.hasOwn(eventNames,kind)||!integer(b.minutes,1,1440))throw Error('Неверный тип или длительность');if(['mining','tap'].includes(kind)&&!integer(b.mult,2,20))throw Error('Множитель от 2 до 20');if(kind==='chest'&&(!integer(b.reward,1,1e9)||!integer(b.limit,1,10000)))throw Error('Некорректная награда или лимит');if(c.events.length>=200&&c.events[199].end>t-86400000)throw Error('Слишком много недавних событий');c.events.unshift({id:crypto.randomUUID(),kind,start:t,end:t+b.minutes*60000,mult:['mining','tap'].includes(kind)?b.mult:1,reward:kind==='chest'?b.reward:0,limit:kind==='chest'?b.limit:0,claims:{},scores:{}});c.events=c.events.slice(0,200);detail=eventNames[kind];break;}
 case 'stop':if(!e)throw Error('Нет активного события');e.end=t;detail=eventNames[e.kind];break;
 case 'promo':{const code=clean(b.code,32).toUpperCase();if(!/^[A-Z0-9_-]{3,32}$/.test(code)||Object.hasOwn(c.promos,code))throw Error('Код уже существует или неверный формат');if(Object.keys(c.promos).length>=1000||!integer(b.amount,1,1e9)||!integer(b.limit,1,100000)||!integer(b.minutes,1,43200))throw Error('Некорректные параметры');c.promos[code]={amount:b.amount,limit:b.limit,end:t+b.minutes*60000,used:{}};detail=code;break;}
 case 'disablePromo':{const code=clean(b.code,32).toUpperCase();if(!Object.hasOwn(c.promos,code))throw Error('Код не найден');c.promos[code].disabled=true;detail=code;break;}
 case 'announcement':c.announcement=clean(b.text,500);detail=c.announcement||'Удалено';break;
 case 'maintenance':if(typeof b.enabled!=='boolean')throw Error('Некорректный режим');c.maintenance=b.enabled;detail=String(b.enabled);break;
 case 'block':{const id=String(b.target);if(!isPlayer(id)||isAdmin(id)||typeof b.enabled!=='boolean')throw Error('Некорректный игрок');users[id].v4Blocked=b.enabled;detail=id+' '+String(b.enabled);break;}
 case 'mass':{if(!integer(b.amount,1,b.kind==='boost'?1000:1e9)||!['boost','coins'].includes(b.kind)||!['all','online'].includes(b.scope)||!(/^[a-f0-9-]{36}$/i.test(b.key||'')))throw Error('Некорректные параметры');if(b.kind==='boost'&&!integer(b.i,0,G.boosts.length-1))throw Error('Неизвестный буст');c.massKeys??={};if(Object.hasOwn(c.massKeys,b.key))return {message:'Операция уже выполнена: '+c.massKeys[b.key]};if(Object.keys(c.massKeys).length>=10000)throw Error('Лимит массовых операций');const ids=Object.keys(users).filter(id=>isPlayer(id)&&(b.scope==='all'||(presence.has(id)&&t-presence.get(id)<ONLINE_TTL)));for(const id of ids){const s=users[id];if(b.kind==='coins')bonus(s,b.amount);else{const n=(s.inventory[b.i]||0)+b.amount;if(!Number.isSafeInteger(n))throw Error('Лимит инвентаря');s.inventory[b.i]=n;}}c.massKeys[b.key]=ids.length;detail=b.kind+' ×'+b.amount+' / '+ids.length+' игроков';break;}
 case 'reply':{const x=c.tickets.find(v=>v.id===b.id);if(!x)throw Error('Обращение не найдено');x.reply=clean(b.text,500);if(!x.reply)throw Error('Пустой ответ');detail=x.id;break;}
 default:throw Error('Неизвестная операция');}logV4(uid,b.op,detail,t);return {message:'Готово: '+detail};});}
function playerV4(uid,b,t){const c=cfg(),s=users[uid];if(b.op==='status')return publicV4(uid,t);if(b.op==='tickets')return {tickets:c.tickets.filter(x=>x.uid===uid).slice(0,10)};if(!s)throw Error('Сначала открой игру');if(s.v4Blocked&&!isAdmin(uid)||c.maintenance&&!isAdmin(uid)){if(b.op!=='ticket')throw Error('Игра временно недоступна');}
 return transaction(()=>{if(b.op==='redeem'){const code=clean(b.code,32).toUpperCase(),p=Object.hasOwn(c.promos,code)?c.promos[code]:null;if(!p||p.disabled||p.end<=t||Object.keys(p.used).length>=p.limit||p.used[uid])throw Error('Код недоступен или уже использован');bonus(s,p.amount);p.used[uid]=t;return {message:'Получено '+p.amount+' бонусных POINTS'};}
 if(b.op==='chest'){const e=activeEvent(t);if(!e||e.kind!=='chest'||e.claims[uid]||Object.keys(e.claims).length>=e.limit)throw Error('Сундук недоступен');bonus(s,e.reward);e.claims[uid]=t;return {message:'Получено '+e.reward+' бонусных POINTS'};}
 if(b.op==='ticket'){const v=clean(b.text,500);if(v.length<5||c.tickets.length>=5000||c.tickets.some(x=>x.uid===uid&&t-x.t<60000))throw Error('Введите сообщение от 5 символов; не чаще раза в минуту');c.tickets.unshift({id:crypto.randomUUID(),uid,text:v,t,reply:''});return {message:'Обращение отправлено'};}throw Error('Неизвестная операция');});}
// Extend passive mining only during actual event/lease overlap; extra rewards are bonus POINTS.
function repairMiningState(s,t){
 const d=G.fresh(t);
 for(const k of ['base','bonus','total','taps','reserve','energy','tapCredit','tapStamp','stamp','lease','vip','temp','tempMult']){
   if(typeof s[k]==='string'&&s[k].trim()!==''&&Number.isFinite(Number(s[k])))s[k]=Number(s[k]);
   if(!Number.isFinite(s[k])||s[k]<0)s[k]=d[k];
 }
 for(const k of ['gear','tech','inventory','claimed']){
   if(!Array.isArray(s[k]))s[k]=d[k].slice();
   else for(let i=0;i<d[k].length;i++)if(k==='claimed'){s[k][i]=s[k][i]===true;}else if(!Number.isFinite(s[k][i])||s[k][i]<0){s[k][i]=d[k][i];}
 }
 if(!Array.isArray(s.history))s.history=[];
 if(s.v!==1&&s.v!==2)s.v=d.v;
 if(s.stamp>t)s.stamp=t;
 if(s.tapStamp>t)s.tapStamp=t;
 s.tapCredit=Math.min(12,s.tapCredit);
 return s;
}
const originalTick=G.tick;G.tick=function(s,t=Date.now()){repairMiningState(s,t);const start=s.stamp,lease=s.lease,rate=G.rate(s);for(const x of cfg().events){if(x.kind!=='mining'||x.end<=start||x.start>=t)continue;const ms=Math.max(0,Math.min(t,lease,x.end)-Math.max(start,x.start));if(ms)bonus(s,rate*ms/3600000*(x.mult-1));}return originalTick(s,t);};
function gameV4(uid,s,a,t){const c=cfg(),e=activeEvent(t);if(!isAdmin(uid)&&(s.v4Blocked||c.maintenance)&&a.type!=='sync')return {ok:false,msg:'Игра временно недоступна',state:s};
 G.tick(s,t);const prevTaps=s.taps,prevTotal=s.total,prevBalance=G.balance(s); if(e?.kind==='energy')s.energy=G.maxEnergy(s);
 const out=G.apply(s,a,t,false),taps=s.taps-prevTaps;if(e?.kind==='energy')s.energy=G.maxEnergy(s);
 if(out.ok&&taps>0&&e?.kind==='tap')bonus(s,(s.total-prevTotal)*(e.mult-1));
 if(out.ok&&taps>0&&e?.kind==='tournament'&&!isAdmin(uid))e.scores[uid]=(e.scores[uid]||0)+taps;
 if(a.type==='tap')out.tap={accepted:Math.max(0,taps),earned:Math.max(0,G.balance(s)-prevBalance),balance:Math.floor(G.balance(s))};
 return out;}

